use parseapi::Ip;
#[test]fn ip_deep_expansion(){let value:Ip=serde_json::from_str(r#"{"ip":"198.51.100.10","country":"XX","country_name":"Example","continent":"NA","asn":"AS64512","asn_name":"Fixture","city":"Example","state":"EX","state_name":"Example state","postal":"00123","latitude":0,"longitude":-0.000001,"timezone":"Etc/UTC","network":"198.51.100.0/24","asn_type":"education","registry":"arin","datacenter":false,"relay":false,"tor":false,"vpn":false,"proxy":false,"provider":null}"#).unwrap();let d=value.clone();assert_eq!(d.latitude,Some(0.0));assert_eq!(d.longitude,Some(-0.000001));assert_eq!(d.postal.as_deref(),Some("00123"));assert_eq!(d.proxy,Some(false));assert_eq!(d.state_name.as_deref(),Some("Example state"));assert_eq!(d.timezone.as_deref(),Some("Etc/UTC"));assert_eq!(d.network.as_deref(),Some("198.51.100.0/24"));assert_eq!(d.asn_type.as_deref(),Some("education"));for text in [r#"{"ip":"198.51.100.10"}"#,r#"{"ip":"198.51.100.10"}"#,r#"{"ip":"198.51.100.10","latitude":null,"longitude":null,"proxy":null}"#]{let old:Ip=serde_json::from_str(text).unwrap();{let deep=old;assert!(deep.latitude.is_none()&&deep.proxy.is_none());}}}
